use std::collections::HashMap;

/// Tracks per-key rate limits with a fixed window.
pub struct Limiter {
    window_ms: u64,
    max: u32,
    hits: HashMap<String, (u64, u32)>,
}

impl Limiter {
    pub fn new(window_ms: u64, max: u32) -> Self {
        Self { window_ms, max, hits: HashMap::new() }
    }

    pub fn check(&mut self, key: &str, now_ms: u64) -> bool {
        let entry = self.hits.entry(key.to_string()).or_insert((now_ms, 0));
        if now_ms.saturating_sub(entry.0) >= self.window_ms {
            *entry = (now_ms, 0);
        }
        if entry.1 >= self.max {
            return false;
        }
        entry.1 += 1;
        true
    }

    pub fn prune(&mut self, now_ms: u64) -> usize {
        let before = self.hits.len();
        let w = self.window_ms;
        self.hits.retain(|_, (start, _)| now_ms.saturating_sub(*start) < w);
        before - self.hits.len()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn blocks_after_max_hits_in_window() {
        let mut l = Limiter::new(1_000, 2);
        assert!(l.check("a", 0));
        assert!(l.check("a", 10));
        assert!(!l.check("a", 20));
        assert!(l.check("a", 1_000));
        assert_eq!(l.prune(5_000), 1);
    }
}

import dataclasses
from typing import Iterable


@dataclasses.dataclass
class Invoice:
    number: str
    lines: list[tuple[str, int, float]]
    discount: float = 0.0

    def subtotal(self) -> float:
        return sum(qty * price for _, qty, price in self.lines)

    def total(self) -> float:
        sub = self.subtotal()
        return round(sub - sub * self.discount, 2)


def overdue(invoices: Iterable[Invoice], paid: set[str]) -> list[str]:
    """Numbers of invoices that are not in the paid set, largest total first."""
    pending = [i for i in invoices if i.number not in paid]
    pending.sort(key=lambda i: i.total(), reverse=True)
    return [i.number for i in pending]


if __name__ == "__main__":
    a = Invoice("INV-001", [("widget", 3, 9.5), ("bolt", 40, 0.12)], discount=0.1)
    b = Invoice("INV-002", [("gear", 1, 120.0)])
    print(a.total(), b.total(), overdue([a, b], {"INV-002"}))
